content.css:
.sl-root {
  position: relative;
  overflow: hidden;
  background: #1c1e1a;
  user-select: none;
  outline: none;
  container-type: size;
  font-family: "Bahnschrift Condensed", "Bahnschrift", "Arial Narrow", "Roboto Condensed", "DIN Condensed", sans-serif;
  font-stretch: condensed;
}
.sl-root canvas {
  display: block;
  touch-action: none;
}
.sl-root.sl-engaged,
.sl-root.sl-engaged * {
  cursor: none;
}
.sl-hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  color: #d6cea9;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.7);
}
.sl-play {
  position: absolute;
  inset: 0;
}
.sl-stats {
  position: absolute;
  left: 14px;
  top: 12px;
  display: flex;
  gap: 6px;
}
.sl-stat {
  background: rgba(18, 20, 16, 0.78);
  border-left: 2px solid #ff7a1a;
  padding: 3px 10px 4px;
}
.sl-stat-v {
  color: #f3efe2;
  font-weight: 700;
  font-size: clamp(15px, 4.2cqmin, 28px);
  line-height: 1.1;
}
.sl-stat-l {
  color: #8f8a72;
  font-size: 10px;
  letter-spacing: 0.14em;
}
.sl-timer {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  white-space: nowrap;
}
.sl-timer-l {
  color: #8f8a72;
  font-size: 11px;
  letter-spacing: 0.22em;
}
.sl-timer-v {
  color: #f3efe2;
  font-weight: 700;
  font-size: clamp(20px, 5.5cqmin, 40px);
  line-height: 1.05;
}
.sl-timer-v.urgent {
  color: #ff7a1a;
}
.sl-timer-s {
  font-size: 11px;
  letter-spacing: 0.12em;
}
.sl-feed {
  position: absolute;
  top: 12px;
  right: 14px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}
.sl-kf {
  background: rgba(18, 20, 16, 0.78);
  padding: 3px 8px;
  font-size: clamp(10px, 2.2cqmin, 13px);
  white-space: nowrap;
}
.sl-kf.mine .sl-kf-a {
  color: #ff7a1a;
}
.sl-kf-a,
.sl-kf-b {
  color: #f3efe2;
}
.sl-kf-w {
  color: #8f8a72;
  margin: 0 6px;
}
.sl-kf-t {
  margin-left: 8px;
  color: #d6cea9;
}
.sl-joy {
  display: none;
  position: absolute;
  left: 50%;
  top: 50%;
  width: 12%;
  height: 12%;
  transform: translate(-50%, -50%);
  border: 1px dashed rgba(214, 206, 170, 0.28);
  border-radius: 50%;
}
.sl-kf-hs {
  margin-left: 6px;
  padding: 0 3px;
  color: #ff7a1a;
  border: 1px solid #ff7a1a;
  font-size: 0.8em;
}
.sl-cross,
.sl-hit {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0;
  height: 0;
}
.sl-cross-bar {
  position: absolute;
  left: 0;
  top: 0;
  background: rgba(243, 239, 226, 0.92);
  box-shadow: 0 0 2px rgba(0, 0, 0, 0.9);
}
.sl-cross-bar:nth-child(1),
.sl-cross-bar:nth-child(2) {
  width: 2px;
  height: 9px;
}
.sl-cross-bar:nth-child(3),
.sl-cross-bar:nth-child(4) {
  width: 9px;
  height: 2px;
}
.sl-cross-dot {
  position: absolute;
  width: 2px;
  height: 2px;
  transform: translate(-50%, -50%);
  background: #f3efe2;
}
.sl-hit {
  opacity: 0;
  transition: opacity 0.14s ease-out;
}
.sl-hit.on {
  opacity: 1;
  transition: none;
}
.sl-hit.head .sl-hit-bar {
  background: #e2483a;
}
.sl-hit.kill .sl-hit-bar {
  height: 15px;
}
.sl-hit-bar {
  position: absolute;
  width: 2px;
  height: 10px;
  background: #f3efe2;
  box-shadow: 0 0 2px rgba(0, 0, 0, 0.9);
}
.sl-hit-bar:nth-child(1) {
  transform: translate(-50%, -50%) rotate(45deg) translateY(-13px);
}
.sl-hit-bar:nth-child(2) {
  transform: translate(-50%, -50%) rotate(135deg) translateY(-13px);
}
.sl-hit-bar:nth-child(3) {
  transform: translate(-50%, -50%) rotate(225deg) translateY(-13px);
}
.sl-hit-bar:nth-child(4) {
  transform: translate(-50%, -50%) rotate(315deg) translateY(-13px);
}
.sl-dmg {
  position: absolute;
  left: 50%;
  top: 50%;
  width: clamp(140px, 40cqmin, 280px);
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
}
.sl-dmg-arc {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 6px solid transparent;
  border-top-color: rgba(226, 72, 58, 0.95);
  opacity: 0;
  filter: drop-shadow(0 0 6px rgba(226, 72, 58, 0.8));
}
.sl-vignette {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(ellipse at center, rgba(0, 0, 0, 0) 42%, rgba(140, 12, 6, 0.85) 100%);
}
.sl-scope {
  position: absolute;
  inset: 0;
  display: none;
  background: radial-gradient(circle closest-side at 50% 50%, rgba(0, 0, 0, 0) 95%, #050605 97%);
}
.sl-scope-h,
.sl-scope-v {
  position: absolute;
  background: rgba(0, 0, 0, 0.85);
}
.sl-scope-h {
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
}
.sl-scope-v {
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
}
.sl-scope-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: #ff7a1a;
}
.sl-banner {
  position: absolute;
  top: 22%;
  left: 50%;
  transform: translateX(-50%);
  padding: 6px 48px;
  color: #f3efe2;
  font-size: clamp(15px, 4.4cqmin, 30px);
  letter-spacing: 0.25em;
  white-space: nowrap;
  opacity: 0;
  background: linear-gradient(90deg, rgba(18, 20, 16, 0), rgba(18, 20, 16, 0.75), rgba(18, 20, 16, 0));
}
.sl-prompt {
  position: absolute;
  left: 50%;
  bottom: 54px;
  transform: translateX(-50%);
  color: #ff7a1a;
  font-size: 13px;
  letter-spacing: 0.22em;
  white-space: nowrap;
}
.sl-radar {
  position: absolute;
  left: 14px;
  bottom: 12px;
  width: clamp(86px, 24cqmin, 150px);
}
.sl-mini {
  width: 100%;
  aspect-ratio: 1;
  display: block;
}
.sl-hp {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 5px;
}
.sl-hp-v {
  width: 28px;
  color: #f3efe2;
  font-weight: 700;
  font-size: 15px;
}
.sl-hp-bar {
  flex: 1;
  height: 5px;
  background: rgba(255, 255, 255, 0.14);
}
.sl-hp-fill {
  height: 100%;
  background: #d6cea9;
}
.sl-hp-fill.low {
  background: #e2483a;
}
.sl-bar {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  max-width: 50%;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 3px;
}
.sl-slot {
  background: rgba(18, 20, 16, 0.78);
  padding: 4px 8px;
  color: #8f8a72;
  font-size: clamp(9px, 1.9cqmin, 12px);
  white-space: nowrap;
  border-bottom: 2px solid transparent;
}
.sl-slot.active {
  color: #f3efe2;
  border-bottom-color: #ff7a1a;
}
.sl-slot-k {
  margin-right: 5px;
  color: #d6cea9;
}
.sl-ammo {
  position: absolute;
  right: 16px;
  bottom: 12px;
  min-width: 120px;
  text-align: right;
}
.sl-ammo-mag {
  color: #f3efe2;
  font-weight: 700;
  font-size: clamp(26px, 8cqmin, 56px);
  line-height: 1;
}
.sl-ammo-mag.low {
  color: #ff7a1a;
}
.sl-ammo-res {
  color: #8f8a72;
  font-size: clamp(14px, 3.6cqmin, 24px);
}
.sl-ammo-name {
  font-size: clamp(11px, 2.4cqmin, 15px);
  letter-spacing: 0.14em;
}
.sl-ammo-class {
  color: #8f8a72;
  font-size: 10px;
  letter-spacing: 0.2em;
}
.sl-reload {
  height: 3px;
  margin-top: 4px;
  background: rgba(255, 255, 255, 0.15);
  visibility: hidden;
}
.sl-reload-fill {
  height: 100%;
  background: #ff7a1a;
}
.sl-board {
  position: absolute;
  left: 50%;
  top: 50%;
  display: none;
  min-width: min(480px, 84%);
  transform: translate(-50%, -50%);
  padding: 12px 16px;
  background: rgba(18, 20, 16, 0.92);
  border-top: 2px solid #ff7a1a;
}
.sl-board table {
  width: 100%;
  border-collapse: collapse;
}
.sl-board th {
  color: #8f8a72;
  font-size: 10px;
  font-weight: 400;
  text-align: left;
  padding: 4px 8px;
  letter-spacing: 0.14em;
}
.sl-board td {
  color: #f3efe2;
  font-size: 13px;
  padding: 4px 8px;
  border-top: 1px solid rgba(214, 206, 170, 0.12);
}
.sl-board tr.me td {
  color: #ff7a1a;
}
.sl-board-t {
  color: #f3efe2;
  letter-spacing: 0.3em;
  margin-bottom: 6px;
}
.sl-panel {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  background: rgba(14, 15, 12, 0.55);
}
.sl-panel.pause .sl-panel-in {
  text-align: center;
}
.sl-panel-in {
  max-width: min(780px, 94%);
  max-height: 94%;
  overflow: auto;
  padding: clamp(12px, 3cqmin, 26px);
  background: rgba(20, 22, 18, 0.9);
  border-top: 3px solid #ff7a1a;
}
.sl-brand-t {
  color: #f3efe2;
  font-weight: 700;
  font-size: clamp(26px, 8cqmin, 56px);
  letter-spacing: 0.3em;
  line-height: 1;
}
.sl-brand-s {
  color: #8f8a72;
  font-size: 11px;
  letter-spacing: 0.4em;
  margin: 4px 0 14px;
}
.sl-modes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
@container (max-width: 560px) {
  .sl-modes {
    grid-template-columns: 1fr;
  }
}
.sl-mode,
.sl-class,
.sl-btn {
  font: inherit;
  text-transform: uppercase;
  cursor: pointer;
  color: #d6cea9;
}
.sl-mode,
.sl-class {
  text-align: left;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(214, 206, 170, 0.18);
}
.sl-mode:hover,
.sl-class:hover,
.sl-mode:focus-visible,
.sl-class:focus-visible {
  border-color: #ff7a1a;
  background: rgba(255, 122, 26, 0.08);
  outline: none;
}
.sl-mode-k {
  color: #ff7a1a;
  font-size: 11px;
}
.sl-mode-t {
  color: #f3efe2;
  font-weight: 700;
  font-size: clamp(15px, 3.4cqmin, 22px);
  letter-spacing: 0.12em;
}
.sl-mode-d {
  color: #8f8a72;
  font-size: 11px;
  line-height: 1.3;
  margin: 4px 0 8px;
}
.sl-mode-b {
  font-size: 11px;
}
.sl-line {
  margin-top: 12px;
  font-size: 12px;
}
.sl-line.dim {
  margin-top: 4px;
  color: #8f8a72;
}
.sl-help {
  margin-top: 10px;
  color: #8f8a72;
  font-size: 10px;
  line-height: 1.6;
  letter-spacing: 0.08em;
}
.sl-sum-t {
  color: #f3efe2;
  font-weight: 700;
  font-size: clamp(24px, 7cqmin, 48px);
  letter-spacing: 0.25em;
}
.sl-sum-s {
  color: #8f8a72;
  font-size: 12px;
  letter-spacing: 0.2em;
  margin-bottom: 14px;
}
.sl-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 8px;
}
.sl-tile {
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.04);
  border-left: 2px solid #6b6f4a;
}
.sl-tile.best {
  border-left-color: #ff7a1a;
}
.sl-tile-v {
  color: #f3efe2;
  font-weight: 700;
  font-size: clamp(20px, 5cqmin, 32px);
}
.sl-tile-l {
  color: #8f8a72;
  font-size: 10px;
  letter-spacing: 0.14em;
}
.sl-tile-nb {
  color: #ff7a1a;
  font-size: 10px;
  letter-spacing: 0.16em;
}
.sl-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}
.sl-btn {
  padding: 8px 14px;
  background: transparent;
  border: 1px solid rgba(214, 206, 170, 0.3);
  letter-spacing: 0.15em;
}
.sl-btn.primary {
  background: #ff7a1a;
  border-color: #ff7a1a;
  color: #15140f;
}
.sl-classes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-top: 10px;
}
@container (max-width: 560px) {
  .sl-classes {
    grid-template-columns: 1fr 1fr;
  }
}
.sl-class {
  padding: 6px 10px;
}
.sl-class.active {
  border-color: #ff7a1a;
  background: rgba(255, 122, 26, 0.14);
}
.sl-class-t {
  color: #f3efe2;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.12em;
}
.sl-class-d {
  color: #8f8a72;
  font-size: 10px;
  line-height: 1.3;
}
.sl-buttons .sl-line {
  align-self: center;
  margin: 0;
}
.sl-ce-name {
  width: 100%;
  box-sizing: border-box;
  padding: 2px 6px;
  font: inherit;
  font-weight: 700;
  font-size: clamp(24px, 7cqmin, 48px);
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: #f3efe2;
  background: transparent;
  border: 1px solid transparent;
  border-bottom-color: rgba(214, 206, 170, 0.3);
}
.sl-ce-name:hover,
.sl-ce-name:focus {
  border-color: #ff7a1a;
  outline: none;
}
.sl-ce {
  display: grid;
  grid-template-columns: 90px auto 1fr auto;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  padding: 6px 8px;
  background: rgba(255, 255, 255, 0.04);
}
.sl-ce-l {
  color: #ff7a1a;
  font-size: 11px;
  letter-spacing: 0.16em;
}
.sl-ce-n {
  color: #f3efe2;
  font-weight: 700;
  font-size: clamp(14px, 3cqmin, 20px);
  letter-spacing: 0.1em;
}
.sl-ce-d {
  color: #8f8a72;
  font-size: 10px;
  letter-spacing: 0.08em;
}
@container (max-height: 460px) {
  .sl-brand-t {
    font-size: 24px;
  }
  .sl-brand-s {
    margin-bottom: 8px;
  }
  .sl-mode-d,
  .sl-help,
  .sl-line.dim {
    display: none;
  }
  .sl-mode {
    padding: 6px 10px;
  }
  .sl-classes,
  .sl-buttons {
    margin-top: 6px;
  }
  .sl-line {
    margin-top: 6px;
  }
  .sl-btn {
    padding: 5px 10px;
  }
}
.sl-zones {
  display: flex;
  justify-content: center;
  gap: 6px;
  margin-top: 4px;
}
.sl-zone {
  position: relative;
  width: 26px;
  height: 26px;
  line-height: 26px;
  text-align: center;
  font-weight: 700;
  color: #f3efe2;
  background: rgba(20, 22, 18, 0.7);
  border: 2px solid rgba(214, 206, 170, 0.5);
}
.sl-zone.mine {
  border-color: #4aa3ff;
  color: #9fd0ff;
}
.sl-zone.theirs {
  border-color: #e2483a;
  color: #ff9a8f;
}
.sl-zone.here {
  outline: 2px solid #f3efe2;
}
.sl-zone-f {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 3px;
}
.sl-diag {
  position: absolute;
  left: 14px;
  top: 74px;
  padding: 4px 6px;
  color: #d6cea9;
  background: rgba(0, 0, 0, 0.45);
  font-size: 10px;
  line-height: 1.35;
  white-space: pre;
  pointer-events: none;
}
